-- Base de Súmulas do STJ — 676 verbetes, com SITUAÇÃO conferida.
--
-- Fecha a última lacuna de situação do Nível 1. Até aqui o STJ era o caso mais
-- perigoso da base: ao contrário do STF — que parou de editar súmulas comuns em
-- 2003 —, o STJ CONTINUA editando e cancelando. Tínhamos 553 enunciados sem
-- data e sem situação; um advogado que citasse a Súmula 603 (retenção de salário
-- por banco, cancelada em 2018) receberia confirmação de uma súmula morta.
--
-- FONTE: STJ — "Verbetes das Súmulas" (scon.stj.jus.br/SCON/sumstj/), lista
-- viva, e "Súmulas Canceladas" como conferência cruzada independente.
-- Extração determinística por tipografia (scripts/extrai_sumulas_stj.py):
-- glifo ZapfDingbats abre o verbete, MuseoSans-700 dá o número, NotoSerif é o
-- corpo. 676 verbetes, 1 a 676, sem lacuna e sem duplicata; a amarração entre o
-- número do cabeçalho e o número repetido na citação de fecho confere em 651 de
-- 676 (os 25 restantes usam o formato novo, que não repete o número).
--
-- ARMADILHA ANOTADA: o glifo que abre o verbete fica 2pt ABAIXO do número que
-- ele anuncia. Ordenar os spans só pela vertical inverte os dois e desloca TODOS
-- os números em uma posição — 676 registros bem formados e integralmente
-- errados. Só a conferência de amarração revelou (648 de 648 quebradas, no
-- padrão 1->2, 2->3). Agrupa-se por linha visual antes de ordenar pela
-- horizontal.
--
-- CONFERÊNCIA CRUZADA: as 29 canceladas batem com a publicação avulsa de
-- canceladas, com uma diferença explicada — a Súmula 222 foi cancelada em
-- 13/11/2024 e aquela publicação é de 2019. Mais uma vez: o texto não muda, a
-- situação muda.
--
-- 'alterada' (5 verbetes) NÃO é o mesmo que cancelada: o enunciado vigente é o
-- que está aqui, e o texto ANTIGO fica em redacao_anterior. Serve para dizer a
-- quem cita a redação velha — Súmulas 309, 545 e 630 circulam em manuais com o
-- texto superado — exatamente o que aconteceu, em vez de só acusar divergência.
--
-- Aditiva. Reversível: drop table public.stj_sumulas cascade;

create table if not exists public.stj_sumulas (
  id              uuid primary key default gen_random_uuid(),
  numero          int  not null,
  enunciado       text not null,
  ramo            text,
  orgao           text,
  data_julgamento date,
  veiculo         text,
  data_publicacao date,
  situacao        text not null default 'nao_verificada',
  nota_situacao   text,
  redacao_anterior text,
  fonte_documento text,
  fonte_arquivo   text,
  fonte_pagina    int,
  fonte_url       text,
  situacao_fonte  text,
  situacao_data   date,
  confianca       text not null default 'alta',
  constraint stj_sumulas_situacao_check
    check (situacao in ('vigente', 'superada', 'cancelada', 'revogada',
                        'alterada', 'prejudicada', 'nao_verificada'))
);

create unique index if not exists uq_stj_sumulas on public.stj_sumulas (numero);
create index if not exists idx_stj_sumulas_trgm
  on public.stj_sumulas using gin (enunciado gin_trgm_ops);

alter table public.stj_sumulas enable row level security;
drop policy if exists stj_sumulas_select on public.stj_sumulas;
create policy stj_sumulas_select on public.stj_sumulas for select
  to authenticated using (true);

comment on column public.stj_sumulas.situacao is
  'Situação conferida na lista viva do STJ. "alterada" significa que o enunciado AQUI é o vigente e o anterior está em redacao_anterior — não que a súmula tenha caído.';
comment on column public.stj_sumulas.data_publicacao is
  'Publicação do enunciado (DJ/DJe/DJEN). Republicação (REPDJe) não substitui a publicação definitiva.';

