  (506, 'A Anatel não é parte legítima nas demandas entre a concessionária e o usuário de telefonia decorrentes de relação contratual.', null, 'PRIMEIRA SEÇÃO', date '2014-03-26', 'DJe', date '2014-03-31', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 26, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (507, 'A acumulação de auxílio-acidente com aposentadoria pressupõe que a lesão incapacitante e a aposentadoria sejam anteriores a 11/11/1997, observado o critério do art. 23 da Lei n. 8.213/1991 para definição do momento da lesão nos casos de doença profissional ou do trabalho.', null, 'PRIMEIRA SEÇÃO', date '2014-03-26', 'DJe', date '2014-03-31', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 26, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (508, 'A isenção da Cofins concedida pelo art. 6º, II, da LC n. 70/1991 às sociedades civis de prestação de serviços profissionais foi revogada pelo art. 56 da Lei n. 9.430/1996.', null, 'PRIMEIRA SEÇÃO', date '2014-03-26', 'DJe', date '2014-03-31', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 26, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (509, 'É lícito ao comerciante de boa-fé aproveitar os créditos de ICMS decorrentes de nota fiscal posteriormente declarada inidônea, quando demonstrada a veracidade da compra e venda.', null, 'PRIMEIRA SEÇÃO', date '2014-03-26', 'DJe', date '2014-03-31', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 26, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (510, 'A liberação de veículo retido apenas por transporte irregular de passageiros não está condicionada ao pagamento de multas e despesas.', null, 'PRIMEIRA SEÇÃO', date '2014-03-26', 'DJe', date '2014-03-31', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 26, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (511, 'É possível o reconhecimento do privilégio previsto no § 2º do art. 155 do CP nos casos de crime de furto qualificado, se estiverem presentes a primariedade do agente, o pequeno valor da coisa e a qualificadora for de ordem objetiva.', null, 'TERCEIRA SEÇÃO', date '2014-06-11', 'DJe', date '2014-06-16', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 26, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (512, 'A aplicação da causa de diminuição de pena prevista no art. 33, § 4º, da Lei n. 11.343/2006 não afasta a hediondez do crime de tráfico de drogas.', 'DIREITO PENAL - TRÁFICO DE DROGAS', 'TERCEIRA SEÇÃO', date '2014-06-11', 'DJe', date '2014-06-16', 'cancelada', 'SÚMULA CANCELADA: A Terceira Seção, na sessão de 23/11/2016, ao julgar a QO na Pet 11.796/DF, determinou o CANCELAMENTO da Súmula 512 do STJ (DJ 28/11/2016).', null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 26, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (513, 'A ''abolitio criminis'' temporária prevista na Lei n. 10.826/2003 aplica-se ao crime de posse de arma de fogo de uso permitido com numeração, marca ou qualquer outro sinal de identificação raspado, suprimido ou adulterado, praticado somente até 23/10/2005.', null, 'TERCEIRA SEÇÃO', date '2014-06-11', 'DJe', date '2014-06-16', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 25, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (514, 'A CEF é responsável pelo fornecimento dos extratos das contas individualizadas vinculadas ao FGTS dos Trabalhadores participantes do Fundo de Garantia do Tempo de Serviço, inclusive para fins de exibição em juízo, independentemente do período em discussão.', null, 'PRIMEIRA SEÇÃO', date '2014-08-14', 'DJe', date '2014-08-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 25, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (515, 'A reunião de execuções fiscais contra o mesmo devedor constitui faculdade do Juiz.', null, 'PRIMEIRA SEÇÃO', date '2014-08-14', 'DJe', date '2014-08-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 25, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (516, 'A contribuição de intervenção no domínio econômico para o Incra (Decreto-Lei n. 1.110/1970), devida por empregadores rurais e urbanos, não foi extinta pelas Leis ns. 7.787/1989, 8.212/1991 e 8.213/1991, não podendo ser compensada com a contribuição ao INSS.', null, 'PRIMEIRA SEÇÃO', date '2015-02-25', 'DJe', date '2015-03-02', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 25, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (517, 'São devidos honorários advocatícios no cumprimento de sentença, haja ou não impugnação, depois de escoado o prazo para pagamento voluntário, que se inicia após a intimação do advogado da parte executada.', null, 'CORTE ESPECIAL', date '2015-02-26', 'DJe', date '2015-03-02', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 25, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (518, 'Para fins do art. 105, III, a, da Constituição Federal, não é cabível recurso especial fundado em alegada violação de enunciado de súmula.', null, 'CORTE ESPECIAL', date '2015-02-26', 'DJe', date '2015-03-02', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 25, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (519, 'Na hipótese de rejeição da impugnação ao cumprimento de sentença, não são cabíveis honorários advocatícios.', null, 'CORTE ESPECIAL', date '2015-02-26', 'DJe', date '2015-03-09', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 25, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (520, 'O benefício de saída temporária no âmbito da execução penal é ato jurisdicional insuscetível de delegação à autoridade administrativa do estabelecimento prisional.', null, 'TERCEIRA SEÇÃO', date '2015-03-25', 'DJe', date '2015-04-06', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 24, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (521, 'A legitimidade para a execução fiscal de multa pendente de pagamento imposta em sentença condenatória é exclusiva da Procuradoria da Fazenda Pública.', null, 'TERCEIRA SEÇÃO', date '2015-03-25', 'DJe', date '2015-04-06', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 24, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (522, 'A conduta de atribuir-se falsa identidade perante autoridade policial é típica, ainda que em situação de alegada autodefesa.', null, 'TERCEIRA SEÇÃO', date '2015-03-25', 'DJe', date '2015-04-06', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 24, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (523, 'A taxa de juros de mora incidente na repetição de indébito de tributos estaduais deve corresponder à utilizada para cobrança do tributo pago em atraso, sendo legítima a incidência da taxa Selic, em ambas as hipóteses, quando prevista na legislação local, vedada sua cumulação com quaisquer outros índices.', null, 'PRIMEIRA SEÇÃO', date '2015-04-22', 'DJe', date '2015-04-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 24, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (524, 'No tocante à base de cálculo, o ISSQN incide apenas sobre a taxa de agenciamento quando o serviço prestado por sociedade empresária de trabalho temporário for de intermediação, devendo, entretanto, englobar também os valores dos salários e encargos sociais dos trabalhadores por ela contratados nas hipóteses de fornecimento de mão de obra.', null, 'PRIMEIRA SEÇÃO', date '2015-04-22', 'DJe', date '2015-04-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 24, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (525, 'A Câmara de Vereadores não possui personalidade jurídica, apenas personalidade judiciária, somente podendo demandar em juízo para defender os seus direitos institucionais.', null, 'PRIMEIRA SEÇÃO', date '2015-04-22', 'DJe', date '2015-04-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 24, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (526, 'O reconhecimento de falta grave decorrente do cometimento de fato definido como crime doloso no cumprimento da pena prescinde do trânsito em julgado de sentença penal condenatória no processo penal instaurado para apuração do fato.', null, 'TERCEIRA SEÇÃO', date '2015-05-13', 'DJe', date '2015-05-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 24, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (527, 'O tempo de duração da medida de segurança não deve ultrapassar o limite máximo da pena abstratamente cominada ao delito praticado.', null, 'TERCEIRA SEÇÃO', date '2015-05-13', 'DJe', date '2015-05-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 23, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (528, 'Compete ao juiz federal do local da apreensão da droga remetida do exterior pela via postal processar e julgar o crime de tráfico internacional.', 'DIREITO PENAL - TRÁFICO DE DROGAS', 'TERCEIRA SEÇÃO', date '2015-05-13', 'DJe', date '2015-05-18', 'cancelada', 'SÚMULA CANCELADA: A Terceira Seção, na sessão ordinária de 23/02/2022, ao apreciar o Projeto de Súmula n. 1.258, determinou o CANCELAMENTO da Súmula 528 do STJ (DJe 24/02/2022).', null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 23, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (529, 'No seguro de responsabilidade civil facultativo, não cabe o ajuizamento de ação pelo terceiro prejudicado direta e exclusivamente em face da seguradora do apontado causador do dano.', null, 'SEGUNDA SEÇÃO', date '2015-05-13', 'DJe', date '2015-05-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 23, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (530, 'Nos contratos bancários, na impossibilidade de comprovar a taxa de juros efetivamente contratada - por ausência de pactuação ou pela falta de juntada do instrumento aos autos -, aplica-se a taxa média de mercado, divulgada pelo Bacen, praticada nas operações da mesma espécie, salvo se a taxa cobrada for mais vantajosa para o devedor.', null, 'SEGUNDA SEÇÃO', date '2015-05-13', 'DJe', date '2015-05-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 23, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (531, 'Em ação monitória fundada em cheque prescrito ajuizada contra o emitente, é dispensável a menção ao negócio jurídico subjacente à emissão da cártula.', null, 'SEGUNDA SEÇÃO', date '2015-05-13', 'DJe', date '2015-05-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 23, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (532, 'Constitui prática comercial abusiva o envio de cartão de crédito sem prévia e expressa solicitação do consumidor, configurando-se ato ilícito indenizável e sujeito à aplicação de multa administrativa.', null, 'CORTE ESPECIAL', date '2015-06-03', 'DJe', date '2015-06-08', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 23, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (533, 'Para o reconhecimento da prática de falta disciplinar no âmbito da execução penal, é imprescindível a instauração de procedimento administrativo pelo diretor do estabelecimento prisional, assegurado o direito de defesa, a ser realizado por advogado constituído ou defensor público nomeado.', null, 'TERCEIRA SEÇÃO', date '2015-06-10', 'DJe', date '2015-06-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 22, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (534, 'A prática de falta grave interrompe a contagem do prazo para a progressão de regime de cumprimento de pena, o qual se reinicia a partir do cometimento dessa infração.', null, 'TERCEIRA SEÇÃO', date '2015-06-10', 'DJe', date '2015-06-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 22, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (535, 'A prática de falta grave não interrompe o prazo para fim de comutação de pena ou indulto.', null, 'TERCEIRA SEÇÃO', date '2015-06-10', 'DJe', date '2015-06-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 22, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (536, 'A suspensão condicional do processo e a transação penal não se aplicam na hipótese de delitos sujeitos ao rito da Lei Maria da Penha.', null, 'TERCEIRA SEÇÃO', date '2015-06-10', 'DJe', date '2015-06-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 22, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (537, 'Em ação de reparação de danos, a seguradora denunciada, se aceitar a denunciação ou contestar o pedido do autor, pode ser condenada, direta e solidariamente junto com o segurado, ao pagamento da indenização devida à vítima, nos limites contratados na apólice.', null, 'SEGUNDA SEÇÃO', date '2015-06-10', 'DJe', date '2015-06-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 22, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (538, 'As administradoras de consórcio têm liberdade para estabelecer a respectiva taxa de administração, ainda que fixada em percentual superior a dez por cento.', null, 'SEGUNDA SEÇÃO', date '2015-06-10', 'DJe', date '2015-06-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 22, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (539, 'É permitida a capitalização de juros com periodicidade inferior à anual em contratos celebrados com instituições integrantes do Sistema Financeiro Nacional a partir de 31/3/2000 (MP n. 1.963- 17/2000, reeditada como MP n. 2.170-36/2001), desde que expressamente pactuada.', null, 'SEGUNDA SEÇÃO', date '2015-06-10', 'DJe', date '2015-06-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 22, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (540, 'Na ação de cobrança do seguro DPVAT, constitui faculdade do autor escolher entre os foros do seu domicílio, do local do acidente ou ainda do domicílio do réu.', null, 'SEGUNDA SEÇÃO', date '2015-06-10', 'DJe', date '2015-06-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 21, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (541, 'A previsão no contrato bancário de taxa de juros anual superior ao duodécuplo da mensal é suficiente para permitir a cobrança da taxa efetiva anual contratada.', null, 'SEGUNDA SEÇÃO', date '2015-06-10', 'DJe', date '2015-06-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 21, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (542, 'A ação penal relativa ao crime de lesão corporal resultante de violência doméstica contra a mulher é pública incondicionada.', null, 'TERCEIRA SEÇÃO', date '2015-08-26', 'DJe', date '2015-08-31', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 21, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (543, 'Na hipótese de resolução de contrato de promessa de compra e venda de imóvel submetido ao Código de Defesa do Consumidor, deve ocorrer a imediata restituição das parcelas pagas pelo promitente comprador - integralmente, em caso de culpa exclusiva do promitente vendedor/construtor, ou parcialmente, caso tenha sido o comprador quem deu causa ao desfazimento.', null, 'SEGUNDA SEÇÃO', date '2015-08-26', 'DJe', date '2015-08-31', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 21, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (544, 'É válida a utilização de tabela do Conselho Nacional de Seguros Privados para estabelecer a proporcionalidade da indenização do seguro DPVAT ao grau de invalidez também na hipótese de sinistro anterior a 16/12/2008, data da entrada em vigor da Medida Provisória n. 451/2008.', null, 'SEGUNDA SEÇÃO', date '2015-08-26', 'DJe', date '2015-08-31', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 21, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (545, 'A confissão do autor possibilita a atenuação da pena prevista no art. 65, III, d, do Código Penal, independentemente de ser utilizada na formação do convencimento do julgador.', null, 'TERCEIRA SEÇÃO', date '2025-09-10', 'DJEN', date '2025-12-02', 'alterada', 'SÚMULA REVISADA: A Terceira Seção, na sessão ordinária de 10/09/2025, ao julgar o REsp 2.001.973/RS (tema repetitivo 1194), deliberou pela REVISÃO do enunciado da Súmula 545.', 'Quando a confissão for utilizada para a formação do convencimento do julgador, o réu fará jus à atenuante prevista no art. 65, III, d, do Código Penal. (SÚMULA 545, TERCEIRA SEÇÃO, julgado em 14/10/2015, DJe de 19/10/2015)', 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 21, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (546, 'A competência para processar e julgar o crime de uso de documento falso é firmada em razão da entidade ou órgão ao qual foi apresentado o documento público, não importando a qualificação do órgão expedidor.', null, 'TERCEIRA SEÇÃO', date '2015-10-14', 'DJe', date '2015-10-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 20, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (547, 'Nas ações em que se pleiteia o ressarcimento dos valores pagos a título de participação financeira do consumidor no custeio de construção de rede elétrica, o prazo prescricional é de vinte anos na vigência do Código Civil de 1916. Na vigência do Código Civil de 2002, o prazo é de cinco anos se houver previsão contratual de ressarcimento e de três anos na ausência de cláusula nesse sentido, observada a regra de transição disciplinada em seu art. 2.028.', null, 'SEGUNDA SEÇÃO', date '2015-10-14', 'DJe', date '2015-10-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 20, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (548, 'Incumbe ao credor a exclusão do registro da dívida em nome do devedor no cadastro de inadimplentes no prazo de cinco dias úteis, a partir do integral e efetivo pagamento do débito.', null, 'SEGUNDA SEÇÃO', date '2015-10-14', 'DJe', date '2015-10-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 20, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (549, 'É válida a penhora de bem de família pertencente a fiador de contrato de locação.', null, 'SEGUNDA SEÇÃO', date '2015-10-14', 'DJe', date '2015-10-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 20, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (550, 'A utilização de escore de crédito, método estatístico de avaliação de risco que não constitui banco de dados, dispensa o consentimento do consumidor, que terá o direito de solicitar esclarecimentos sobre as informações pessoais valoradas e as fontes dos dados considerados no respectivo cálculo.', null, 'SEGUNDA SEÇÃO', date '2015-10-14', 'DJe', date '2015-10-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 20, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (551, 'Nas demandas por complementação de ações de empresas de telefonia, admite-se a condenação ao pagamento de dividendos e juros sobre capital próprio independentemente de pedido expresso. No entanto, somente quando previstos no título executivo, poderão ser objeto de cumprimento de sentença.', null, 'SEGUNDA SEÇÃO', date '2015-10-14', 'DJe', date '2015-10-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 20, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (552, 'O portador de surdez unilateral não se qualifica como pessoa com deficiência para o fim de disputar as vagas reservadas em concursos públicos.', null, 'CORTE ESPECIAL', date '2015-11-04', 'DJe', date '2015-11-09', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 19, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (553, 'Nos casos de empréstimo compulsório sobre o consumo de energia elétrica, é competente a Justiça estadual para o julgamento de demanda proposta exclusivamente contra a Eletrobrás. Requerida a intervenção da União no feito após a prolação de sentença pelo juízo estadual, os autos devem ser remetidos ao Tribunal Regional Federal competente para o julgamento da apelação se deferida a intervenção.', null, 'PRIMEIRA SEÇÃO', date '2015-12-09', 'DJe', date '2015-12-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 19, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (554, 'Na hipótese de sucessão empresarial, a responsabilidade da sucessora abrange não apenas os tributos devidos pela sucedida, mas também as multas moratórias ou punitivas referentes a fatos geradores ocorridos até a data da sucessão.', null, 'PRIMEIRA SEÇÃO', date '2015-12-09', 'DJe', date '2015-12-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 19, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (555, 'Quando não houver declaração do débito, o prazo decadencial quinquenal para o Fisco constituir o crédito tributário conta-se exclusivamente na forma do art. 173, I, do CTN, nos casos em que a legislação atribui ao sujeito passivo o dever de antecipar o pagamento sem prévio exame da autoridade administrativa.', null, 'PRIMEIRA SEÇÃO', date '2015-12-09', 'DJe', date '2015-12-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 19, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (556, 'É indevida a incidência de imposto de renda sobre o valor da complementação de aposentadoria pago por entidade de previdência privada e em relação ao resgate de contribuições recolhidas para referidas entidades patrocinadoras no período de 1º/1/1989 a 31/12/1995, em razão da isenção concedida pelo art. 6º, VII, b, da Lei n. 7.713/1988, na redação anterior à que lhe foi dada pela Lei n. 9.250/1995.', null, 'PRIMEIRA SEÇÃO', date '2015-12-09', 'DJe', date '2015-12-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 19, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (557, 'A renda mensal inicial (RMI) alusiva ao benefício de aposentadoria por invalidez precedido de auxílio-doença será apurada na forma do art. 36, § 7º, do Decreto n. 3.048/1999, observando-se, porém, os critérios previstos no art. 29, § 5º, da Lei n. 8.213/1991, quando intercalados períodos de afastamento e de atividade laboral.', null, 'PRIMEIRA SEÇÃO', date '2015-12-09', 'DJe', date '2015-12-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 19, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (558, 'Em ações de execução fiscal, a petição inicial não pode ser indeferida sob o argumento da falta de indicação do CPF e/ou RG ou CNPJ da parte executada.', null, 'PRIMEIRA SEÇÃO', date '2015-12-09', 'DJe', date '2015-12-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 18, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (559, 'Em ações de execução fiscal, é desnecessária a instrução da petição inicial com o demonstrativo de cálculo do débito, por tratar-se de requisito não previsto no art. 6º da Lei n. 6.830/1980.', null, 'PRIMEIRA SEÇÃO', date '2015-12-09', 'DJe', date '2015-12-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 18, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (560, 'A decretação da indisponibilidade de bens e direitos, na forma do art. 185-A do CTN, pressupõe o exaurimento das diligências na busca por bens penhoráveis, o qual fica caracterizado quando infrutíferos o pedido de constrição sobre ativos financeiros e a expedição de ofícios aos registros públicos do domicílio do executado, ao Denatran ou Detran.', null, 'PRIMEIRA SEÇÃO', date '2015-12-09', 'DJe', date '2015-12-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 18, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (561, 'Os Conselhos Regionais de Farmácia possuem atribuição para fiscalizar e autuar as farmácias e drogarias quanto ao cumprimento da exigência de manter profissional legalmente habilitado (farmacêutico) durante todo o período de funcionamento dos respectivos estabelecimentos.', null, 'PRIMEIRA SEÇÃO', date '2015-12-09', 'DJe', date '2015-12-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 18, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (562, 'É possível a remição de parte do tempo de execução da pena quando o condenado, em regime fechado ou semiaberto, desempenha atividade laborativa, ainda que extramuros.', null, 'TERCEIRA SEÇÃO', date '2016-02-24', 'DJe', date '2016-02-29', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 18, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (563, 'O Código de Defesa do Consumidor é aplicável às entidades abertas de previdência complementar, não incidindo nos contratos previdenciários celebrados com entidades fechadas.', null, 'SEGUNDA SEÇÃO', date '2016-02-24', 'DJe', date '2016-02-29', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 18, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (564, 'No caso de reintegração de posse em arrendamento mercantil financeiro, quando a soma da importância antecipada a título de valor residual garantido (VRG) com o valor da venda do bem ultrapassar o total do VRG previsto contratualmente, o arrendatário terá direito de receber a respectiva diferença, cabendo, porém, se estipulado no contrato, o prévio desconto de outras despesas ou encargos pactuados.', null, 'SEGUNDA SEÇÃO', date '2016-02-24', 'DJe', date '2016-02-29', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 17, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (565, 'A pactuação das tarifas de abertura de crédito (TAC) e de emissão de carnê (TEC), ou outra denominação para o mesmo fato gerador, é válida apenas nos contratos bancários anteriores ao início da vigência da Resolução-CMN n. 3.518/2007, em 30/4/2008.', null, 'SEGUNDA SEÇÃO', date '2016-02-24', 'DJe', date '2016-02-29', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 17, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (566, 'Nos contratos bancários posteriores ao início da vigência da Resolução-CMN n. 3.518/2007, em 30/4/2008, pode ser cobrada a tarifa de cadastro no início do relacionamento entre o consumidor e a instituição financeira.', null, 'SEGUNDA SEÇÃO', date '2016-02-24', 'DJe', date '2016-02-29', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 17, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (567, 'Sistema de vigilância realizado por monitoramento eletrônico ou por existência de segurança no interior de estabelecimento comercial, por si só, não torna impossível a configuração do crime de furto.', null, 'TERCEIRA SEÇÃO', date '2016-02-24', 'DJe', date '2016-02-29', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 17, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (568, 'O relator, monocraticamente e no Superior Tribunal de Justiça, poderá dar ou negar provimento ao recurso quando houver entendimento dominante acerca do tema.', null, 'CORTE ESPECIAL', date '2016-03-16', 'DJe', date '2016-03-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 17, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (569, 'Na importação, é indevida a exigência de nova certidão negativa de débito no desembaraço aduaneiro, se já apresentada a comprovação da quitação de tributos federais quando da concessão do benefício relativo ao regime de drawback.', null, 'PRIMEIRA SEÇÃO', date '2016-04-27', 'DJe', date '2016-05-02', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 17, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (570, 'Compete à Justiça Federal o processo e julgamento de demanda em que se discute a ausência de ou o obstáculo ao credenciamento de instituição particular de ensino superior no Ministério da Educação como condição de expedição de diploma de ensino a distância aos estudantes.', null, 'PRIMEIRA SEÇÃO', date '2016-04-27', 'DJe', date '2016-05-02', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 16, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (571, 'A taxa progressiva de juros não se aplica às contas vinculadas ao FGTS de trabalhadores qualificados como avulsos.', null, 'PRIMEIRA SEÇÃO', date '2016-04-27', 'DJe', date '2016-05-02', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 16, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (572, 'O Banco do Brasil, na condição de gestor do Cadastro de Emitentes de Cheques sem Fundos (CCF), não tem a responsabilidade de notificar previamente o devedor acerca da sua inscrição no aludido cadastro, tampouco legitimidade passiva para as ações de reparação de danos fundadas na ausência de prévia comunicação.', null, 'SEGUNDA SEÇÃO', date '2016-05-11', 'DJe', date '2016-05-16', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 16, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (573, 'Nas ações de indenização decorrente de seguro DPVAT, a ciência inequívoca do caráter permanente da invalidez, para fins de contagem do prazo prescricional, depende de laudo médico, exceto nos casos de invalidez permanente notória ou naqueles em que o conhecimento anterior resulte comprovado na fase de instrução.', null, 'SEGUNDA SEÇÃO', date '2016-06-22', 'DJe', date '2016-06-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 16, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (574, 'Para a configuração do delito de violação de direito autoral e a comprovação de sua materialidade, é suficiente a perícia realizada por amostragem do produto apreendido, nos aspectos externos do material, e é desnecessária a identificação dos titulares dos direitos autorais violados ou daqueles que os representem.', null, 'TERCEIRA SEÇÃO', date '2016-06-22', 'DJe', date '2016-06-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 16, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (575, 'Constitui crime a conduta de permitir, confiar ou entregar a direção de veículo automotor a pessoa que não seja habilitada, ou que se encontre em qualquer das situações previstas no art. 310 do CTB, independentemente da ocorrência de lesão ou de perigo de dano concreto na condução do veículo.', null, 'TERCEIRA SEÇÃO', date '2016-06-22', 'DJe', date '2016-06-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 16, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (576, 'Ausente requerimento administrativo no INSS, o termo inicial para a implantação da aposentadoria por invalidez concedida judicialmente será a data da citação válida.', null, 'PRIMEIRA SEÇÃO', date '2016-06-22', 'DJe', date '2016-06-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 15, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (577, 'É possível reconhecer o tempo de serviço rural anterior ao documento mais antigo apresentado, desde que amparado em convincente prova testemunhal colhida sob o contraditório.', null, 'PRIMEIRA SEÇÃO', date '2016-06-22', 'DJe', date '2016-06-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 15, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (578, 'Os empregados que laboram no cultivo da cana-de-açúcar para empresa agroindustrial ligada ao setor sucroalcooleiro detêm a qualidade de rurícola, ensejando a isenção do FGTS desde a edição da Lei Complementar n. 11/1971 até a promulgação da Constituição Federal de 1988.', null, 'PRIMEIRA SEÇÃO', date '2016-06-22', 'DJe', date '2016-06-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 15, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (579, 'Não é necessário ratificar o recurso especial interposto na pendência do julgamento dos embargos de declaração, quando inalterado o resultado anterior.', null, 'CORTE ESPECIAL', date '2016-07-01', 'DJe', date '2016-08-01', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 15, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (580, 'A correção monetária nas indenizações do seguro DPVAT por morte ou invalidez, prevista no § 7º do art. 5º da Lei n. 6.194/1974, redação dada pela Lei n. 11.482/2007, incide desde a data do evento danoso.', null, 'SEGUNDA SEÇÃO', date '2016-09-14', 'DJe', date '2016-09-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 15, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (581, 'A recuperação judicial do devedor principal não impede o prosseguimento das ações e execuções ajuizadas contra terceiros devedores solidários ou coobrigados em geral, por garantia cambial, real ou fidejussória.', null, 'SEGUNDA SEÇÃO', date '2016-09-14', 'DJe', date '2016-09-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 15, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (582, 'Consuma-se o crime de roubo com a inversão da posse do bem mediante emprego de violência ou grave ameaça, ainda que por breve tempo e em seguida à perseguição imediata ao agente e recuperação da coisa roubada, sendo prescindível a posse mansa e pacífica ou desvigiada.', null, 'TERCEIRA SEÇÃO', date '2016-09-14', 'DJe', date '2016-09-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 15, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (583, 'O arquivamento provisório previsto no art. 20 da Lei n. 10.522/2002, dirigido aos débitos inscritos como dívida ativa da União pela Procuradoria-Geral da Fazenda Nacional ou por ela cobrados, não se aplica às execuções fiscais movidas pelos conselhos de fiscalização profissional ou pelas autarquias federais.', null, 'PRIMEIRA SEÇÃO', date '2016-12-14', 'DJe', date '2019-05-09', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 14, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (584, 'As sociedades corretoras de seguros, que não se confundem com as sociedades de valores mobiliários ou com os agentes autônomos de seguro privado, estão fora do rol de entidades constantes do art. 22, § 1º, da Lei n. 8.212/1991, não se sujeitando à majoração da alíquota da Cofins prevista no art. 18 da Lei n. 10.684/2003.', null, 'PRIMEIRA SEÇÃO', date '2016-12-14', 'DJe', date '2017-02-01', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 14, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (585, 'A responsabilidade solidária do ex-proprietário, prevista no art. 134 do Código de Trânsito Brasileiro - CTB, não abrange o IPVA incidente sobre o veículo automotor, no que se refere ao período posterior à sua alienação.', null, 'PRIMEIRA SEÇÃO', date '2016-12-14', 'DJe', date '2017-02-01', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 14, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (586, 'A exigência de acordo entre o credor e o devedor na escolha do agente fiduciário aplica-se, exclusivamente, aos contratos não vinculados ao Sistema Financeiro da Habitação - SFH.', null, 'CORTE ESPECIAL', date '2016-12-19', 'DJe', date '2017-02-01', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 14, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (587, 'Para a incidência da majorante prevista no art. 40, V, da Lei n. 11.343/2006, é desnecessária a efetiva transposição de fronteiras entre estados da Federação, sendo suficiente a demonstração inequívoca da intenção de realizar o tráfico interestadual.', null, 'TERCEIRA SEÇÃO', date '2017-09-13', 'DJe', date '2017-09-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 14, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (588, 'A prática de crime ou contravenção penal contra a mulher com violência ou grave ameaça no ambiente doméstico impossibilita a substituição da pena privativa de liberdade por restritiva de direitos.', null, 'TERCEIRA SEÇÃO', date '2017-09-13', 'DJe', date '2017-09-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 14, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (589, 'É inaplicável o princípio da insignificância nos crimes ou contravenções penais praticados contra a mulher no âmbito das relações domésticas.', null, 'TERCEIRA SEÇÃO', date '2017-09-13', 'DJe', date '2017-09-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 13, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (590, 'Constitui acréscimo patrimonial a atrair a incidência do imposto de renda, em caso de liquidação de entidade de previdência privada, a quantia que couber a cada participante, por rateio do patrimônio, superior ao valor das respectivas contribuições à entidade em liquidação, devidamente atualizadas e corrigidas.', null, 'PRIMEIRA SEÇÃO', date '2017-09-13', 'DJe', date '2017-09-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 13, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (591, 'É permitida a prova emprestada no processo administrativo disciplinar, desde que devidamente autorizada pelo juízo competente e respeitados o contraditório e a ampla defesa.', null, 'PRIMEIRA SEÇÃO', date '2017-09-13', 'DJe', date '2017-09-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 13, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (592, 'O excesso de prazo para a conclusão do processo administrativo disciplinar só causa nulidade se houver demonstração de prejuízo à defesa.', null, 'PRIMEIRA SEÇÃO', date '2017-09-13', 'DJe', date '2017-09-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 13, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (593, 'O crime de estupro de vulnerável se configura com a conjunção carnal ou prática de ato libidinoso com menor de 14 anos, sendo irrelevante eventual consentimento da vítima para a prática do ato, sua experiência sexual anterior ou existência de relacionamento amoroso com o agente.', null, 'TERCEIRA SEÇÃO', date '2017-10-25', 'DJe', date '2017-11-06', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 13, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (594, 'O Ministério Público tem legitimidade ativa para ajuizar ação de alimentos em proveito de criança ou adolescente independentemente do exercício do poder familiar dos pais, ou do fato de o menor se encontrar nas situações de risco descritas no art. 98 do Estatuto da Criança e do Adolescente, ou de quaisquer outros questionamentos acerca da existência ou eficiência da Defensoria Pública na comarca.', null, 'SEGUNDA SEÇÃO', date '2017-10-25', 'DJe', date '2017-11-06', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 13, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (595, 'As instituições de ensino superior respondem objetivamente pelos danos suportados pelo aluno/consumidor pela realização de curso não reconhecido pelo Ministério da Educação, sobre o qual não lhe tenha sido dada prévia e adequada informação.', null, 'SEGUNDA SEÇÃO', date '2017-10-25', 'DJe', date '2017-11-06', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 12, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (596, 'A obrigação alimentar dos avós tem natureza complementar e subsidiária, somente se configurando no caso de impossibilidade total ou parcial de seu cumprimento pelos pais.', null, 'SEGUNDA SEÇÃO', date '2017-11-08', 'DJe', date '2017-11-20', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 12, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (597, 'A cláusula contratual de plano de saúde que prevê carência para utilização dos serviços de assistência médica nas situações de emergência ou de urgência é considerada abusiva se ultrapassado o prazo máximo de 24 horas contado da data da contratação.', null, 'SEGUNDA SEÇÃO', date '2017-11-08', 'DJe', date '2017-11-20', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 12, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (598, 'É desnecessária a apresentação de laudo médico oficial para o reconhecimento judicial da isenção do imposto de renda, desde que o magistrado entenda suficientemente demonstrada a doença grave por outros meios de prova.', null, 'PRIMEIRA SEÇÃO', date '2017-11-08', 'DJe', date '2017-11-20', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 12, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (599, 'O princípio da insignificância é inaplicável aos crimes contra a administração pública.', null, 'CORTE ESPECIAL', date '2017-11-20', 'DJe', date '2017-11-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 12, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (600, 'Para a configuração da violência doméstica e familiar prevista no artigo 5º da Lei n. 11.340/2006 (Lei Maria da Penha) não se exige a coabitação entre autor e vítima.', null, 'TERCEIRA SEÇÃO', date '2017-11-22', 'DJe', date '2017-11-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 12, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (601, 'O Ministério Público tem legitimidade ativa para atuar na defesa de direitos difusos, coletivos e individuais homogêneos dos consumidores, ainda que decorrentes da prestação de serviço público.', null, 'CORTE ESPECIAL', date '2018-02-07', 'DJe', date '2018-02-14', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 12, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (602, 'O Código de Defesa do Consumidor é aplicável aos empreendimentos habitacionais promovidos pelas sociedades cooperativas.', null, 'SEGUNDA SEÇÃO', date '2018-02-22', 'DJe', date '2018-02-26', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 11, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (603, 'É vedado ao banco mutuante reter, em qualquer extensão, os salários, vencimentos e/ou proventos de correntista para adimplir o mútuo (comum) contraído, ainda que haja cláusula contratual autorizativa, excluído o empréstimo garantido por margem salarial consignável, com desconto em folha de pagamento, que possui regramento legal específico e admite a retenção de percentual.', 'DIREITO BANCÁRIO - CONTRATO BANCÁRIO', 'SEGUNDA SEÇÃO', date '2018-02-22', 'DJe', date '2018-02-26', 'cancelada', 'SÚMULA CANCELADA: A Segunda Seção, na sessão de 22/08/2018, ao julgar o REsp 1.555.722/SP, determinou o CANCELAMENTO da Súmula 603 do STJ (DJe 27/08/2018).', null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 11, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (604, 'O mandado de segurança não se presta para atribuir efeito suspensivo a recurso criminal interposto pelo Ministério Público.', null, 'TERCEIRA SEÇÃO', date '2018-02-28', 'DJe', date '2018-03-05', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 11, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (605, 'A superveniência da maioridade penal não interfere na apuração de ato infracional nem na aplicabilidade de medida socioeducativa em curso, inclusive na liberdade assistida, enquanto não atingida a idade de 21 anos.', null, 'TERCEIRA SEÇÃO', date '2018-03-14', 'DJe', date '2018-03-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 11, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (606, 'Não se aplica o princípio da insignificância a casos de transmissão clandestina de sinal de internet via radiofrequência, que caracteriza o fato típico previsto no art. 183 da Lei n. 9.472/1997.', null, 'TERCEIRA SEÇÃO', date '2018-04-11', 'DJe', date '2018-04-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 11, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (607, 'A majorante do tráfico transnacional de drogas (art. 40, I, da Lei n. 11.343/2006) configura-se com a prova da destinação internacional das drogas, ainda que não consumada a transposição de fronteiras.', null, 'TERCEIRA SEÇÃO', date '2018-04-11', 'DJe', date '2018-04-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 11, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (608, 'Aplica-se o Código de Defesa do Consumidor aos contratos de plano de saúde, salvo os administrados por entidades de autogestão.', null, 'SEGUNDA SEÇÃO', date '2018-04-11', 'DJe', date '2018-04-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 10, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (609, 'A recusa de cobertura securitária, sob a alegação de doença preexistente, é ilícita se não houve a exigência de exames médicos prévios à contratação ou a demonstração de má-fé do segurado.', null, 'SEGUNDA SEÇÃO', date '2018-04-11', 'DJe', date '2018-04-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 10, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (610, 'O suicídio não é coberto nos dois primeiros anos de vigência do contrato de seguro de vida, ressalvado o direito do beneficiário à devolução do montante da reserva técnica formada.', null, 'SEGUNDA SEÇÃO', date '2018-04-25', 'DJe', date '2018-05-07', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 10, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (611, 'Desde que devidamente motivada e com amparo em investigação ou sindicância, é permitida a instauração de processo administrativo disciplinar com base em denúncia anônima, em face do poder-dever de autotutela imposto à Administração.', null, 'PRIMEIRA SEÇÃO', date '2018-05-09', 'DJe', date '2018-05-14', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 10, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (612, 'O certificado de entidade beneficente de assistência social (CEBAS), no prazo de sua validade, possui natureza declaratória para fins tributários, retroagindo seus efeitos à data em que demonstrado o cumprimento dos requisitos estabelecidos por lei complementar para a fruição da imunidade.', null, 'PRIMEIRA SEÇÃO', date '2018-05-09', 'DJe', date '2018-05-14', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 10, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (613, 'Não se admite a aplicação da teoria do fato consumado em tema de Direito Ambiental.', null, 'PRIMEIRA SEÇÃO', date '2018-05-09', 'DJe', date '2018-05-14', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 10, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (614, 'O locatário não possui legitimidade ativa para discutir a relação jurídico-tributária de IPTU e de taxas referentes ao imóvel alugado nem para repetir indébito desses tributos.', null, 'PRIMEIRA SEÇÃO', date '2018-05-09', 'DJe', date '2018-05-14', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 10, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (615, 'Não pode ocorrer ou permanecer a inscrição do município em cadastros restritivos fundada em irregularidades na gestão anterior quando, na gestão sucessora, são tomadas as providências cabíveis à reparação dos danos eventualmente cometidos.', null, 'PRIMEIRA SEÇÃO', date '2018-05-09', 'DJe', date '2018-05-14', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 9, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (616, 'A indenização securitária é devida quando ausente a comunicação prévia do segurado acerca do atraso no pagamento do prêmio, por constituir requisito essencial para a suspensão ou resolução do contrato de seguro.', null, 'SEGUNDA SEÇÃO', date '2018-05-23', 'DJe', date '2018-05-28', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 9, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (617, 'A ausência de suspensão ou revogação do livramento condicional antes do término do período de prova enseja a extinção da punibilidade pelo integral cumprimento da pena.', null, 'TERCEIRA SEÇÃO', date '2018-09-26', 'DJe', date '2018-10-01', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 9, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (618, 'A inversão do ônus da prova aplica-se às ações de degradação ambiental.', null, 'CORTE ESPECIAL', date '2018-10-24', 'DJe', date '2018-10-30', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 9, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (619, 'A ocupação indevida de bem público configura mera detenção, de natureza precária, insuscetível de retenção ou indenização por acessões e benfeitorias.', null, 'CORTE ESPECIAL', date '2018-10-24', 'DJe', date '2018-10-30', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 9, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (620, 'A embriaguez do segurado não exime a seguradora do pagamento da indenização prevista em contrato de seguro de vida.', null, 'SEGUNDA SEÇÃO', date '2018-12-12', 'DJe', date '2018-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 9, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (621, 'Os efeitos da sentença que reduz, majora ou exonera o alimentante do pagamento retroagem à data da citação, vedadas a compensação e a repetibilidade.', null, 'SEGUNDA SEÇÃO', date '2018-12-12', 'DJe', date '2018-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 9, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (622, 'A notificação do auto de infração faz cessar a contagem da decadência para a constituição do crédito tributário; exaurida a instância administrativa com o decurso do prazo para a impugnação ou com a notificação de seu julgamento definitivo e esgotado o prazo concedido pela Administração para o pagamento voluntário, inicia-se o prazo prescricional para a cobrança judicial.', null, 'PRIMEIRA SEÇÃO', date '2018-12-12', 'DJe', date '2018-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 8, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (623, 'As obrigações ambientais possuem natureza propter rem, sendo admissível cobrá-las do proprietário ou possuidor atual e/ou dos anteriores, à escolha do credor.', null, 'PRIMEIRA SEÇÃO', date '2018-12-12', 'DJe', date '2018-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 8, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (624, 'É possível cumular a indenização do dano moral com a reparação econômica da Lei n. 10.559/2002 (Lei da Anistia Política).', null, 'PRIMEIRA SEÇÃO', date '2018-12-12', 'DJe', date '2018-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 8, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (625, 'O pedido administrativo de compensação ou de restituição não interrompe o prazo prescricional para a ação de repetição de indébito tributário de que trata o art. 168 do CTN nem o da execução de título judicial contra a Fazenda Pública.', null, 'PRIMEIRA SEÇÃO', date '2018-12-12', 'DJe', date '2018-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 8, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (626, 'A incidência do IPTU sobre imóvel situado em área considerada pela lei local como urbanizável ou de expansão urbana não está condicionada à existência dos melhoramentos elencados no art. 32, § 1º, do CTN.', null, 'PRIMEIRA SEÇÃO', date '2018-12-12', 'DJe', date '2018-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 8, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (627, 'O contribuinte faz jus à concessão ou à manutenção da isenção do imposto de renda, não se lhe exigindo a demonstração da contemporaneidade dos sintomas da doença nem da recidiva da enfermidade.', null, 'PRIMEIRA SEÇÃO', date '2018-12-12', 'DJe', date '2018-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 8, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (628, 'A teoria da encampação é aplicada no mandado de segurança quando presentes, cumulativamente, os seguintes requisitos: a) existência de vínculo hierárquico entre a autoridade que prestou informações e a que ordenou a prática do ato impugnado; b) manifestação a respeito do mérito nas informações prestadas; e c) ausência de modificação de competência estabelecida na Constituição Federal.', null, 'PRIMEIRA SEÇÃO', date '2018-12-12', 'DJe', date '2018-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 8, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (629, 'Quanto ao dano ambiental, é admitida a condenação do réu à obrigação de fazer ou à de não fazer cumulada com a de indenizar.', null, 'PRIMEIRA SEÇÃO', date '2018-12-12', 'DJe', date '2018-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 7, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (630, 'A incidência da atenuante da confissão espontânea no crime de tráfico ilícito de entorpecentes quando o acusado admitir a posse ou a propriedade para uso próprio, negando a prática do tráfico de drogas, deve ocorrer em proporção inferior à que seria devida no caso de confissão plena.', null, 'TERCEIRA SEÇÃO', date '2025-09-10', 'DJEN', date '2025-12-02', 'alterada', 'SÚMULA REVISADA: A Terceira Seção, na sessão ordinária de 10/09/2025, ao julgar o REsp 2.001.973/RS (tema repetitivo 1194), deliberou pela REVISÃO do enunciado da Súmula 630.', 'A incidência da atenuante da confissão espontânea no crime de tráfico ilícito de entorpecentes exige o reconhecimento da traficância pelo acusado, não bastando a mera admissão da posse ou propriedade para uso próprio. (SÚMULA 630, TERCEIRA SEÇÃO, julgado em 24/4/2019, DJe de 29/4/2019)', 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 7, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (631, 'O indulto extingue os efeitos primários da condenação (pretensão executória), mas não atinge os efeitos secundários, penais ou extrapenais.', null, 'TERCEIRA SEÇÃO', date '2019-04-24', 'DJe', date '2019-04-29', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 7, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (632, 'Nos contratos de seguro regidos pelo Código Civil, a correção monetária sobre a indenização securitária incide a partir da contratação até o efetivo pagamento.', null, 'SEGUNDA SEÇÃO', date '2019-05-08', 'DJe', date '2019-05-13', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 7, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (633, 'A Lei n. 9.784/1999, especialmente no que diz respeito ao prazo decadencial para a revisão de atos administrativos no âmbito da Administração Pública federal, pode ser aplicada, de forma subsidiária, aos estados e municípios, se inexistente norma local e específica que regule a matéria.', null, 'PRIMEIRA SEÇÃO', date '2019-06-12', 'DJe', date '2019-06-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 7, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (634, 'Ao particular aplica-se o mesmo regime prescricional previsto na Lei de Improbidade Administrativa para o agente público.', null, 'PRIMEIRA SEÇÃO', date '2019-06-12', 'DJe', date '2019-06-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 7, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (635, 'Os prazos prescricionais previstos no art. 142 da Lei n. 8.112/1990 iniciam-se na data em que a autoridade competente para a abertura do procedimento administrativo toma conhecimento do fato, interrompem-se com o primeiro ato de instauração válido - sindicância de caráter punitivo ou processo disciplinar - e voltam a fluir por inteiro, após decorridos 140 dias desde a interrupção.', null, 'PRIMEIRA SEÇÃO', date '2019-06-12', 'DJe', date '2019-06-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 6, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (636, 'A folha de antecedentes criminais é documento suficiente a comprovar os maus antecedentes e a reincidência.', null, 'TERCEIRA SEÇÃO', date '2019-06-26', 'DJe', date '2019-06-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 6, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (637, 'O ente público detém legitimidade e interesse para intervir, incidentalmente, na ação possessória entre particulares, podendo deduzir qualquer matéria defensiva, inclusive, se for o caso, o domínio.', null, 'CORTE ESPECIAL', date '2019-11-06', 'DJe', date '2019-11-11', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 6, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (638, 'É abusiva a cláusula contratual que restringe a responsabilidade de instituição financeira pelos danos decorrentes de roubo, furto ou extravio de bem entregue em garantia no âmbito de contrato de penhor civil.', null, 'SEGUNDA SEÇÃO', date '2019-11-27', 'DJe', date '2019-12-02', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 6, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (639, 'Não fere o contraditório e o devido processo decisão que, sem ouvida prévia da defesa, determine transferência ou permanência de custodiado em estabelecimento penitenciário federal.', null, 'TERCEIRA SEÇÃO', date '2019-11-27', 'DJe', date '2019-12-02', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 6, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (640, 'O benefício fiscal que trata do Regime Especial de Reintegração de Valores Tributários para as Empresas Exportadoras (REINTEGRA) alcança as operações de venda de mercadorias de origem nacional para a Zona Franca de Manaus, para consumo, industrialização ou reexportação para o estrangeiro.', null, 'PRIMEIRA SEÇÃO', date '2020-02-18', 'DJe', date '2020-02-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 6, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (641, 'A portaria de instauração do processo administrativo disciplinar prescinde da exposição detalhada dos fatos a serem apurados.', null, 'PRIMEIRA SEÇÃO', date '2020-02-18', 'DJe', date '2020-02-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 6, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (642, 'O direito à indenização por danos morais transmite-se com o falecimento do titular, possuindo os herdeiros da vítima legitimidade ativa para ajuizar ou prosseguir a ação indenizatória.', null, 'CORTE ESPECIAL', date '2020-12-02', 'DJe', date '2020-12-07', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 5, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (643, 'A execução da pena restritiva de direitos depende do trânsito em julgado da condenação.', null, 'TERCEIRA SEÇÃO', date '2021-02-10', 'DJe', date '2021-02-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 5, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (644, 'O núcleo de prática jurídica deve apresentar o instrumento de mandato quando constituído pelo réu hipossuficiente, salvo nas hipóteses em que é nomeado pelo juízo.', null, 'TERCEIRA SEÇÃO', date '2021-02-10', 'DJe', date '2021-02-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 5, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (645, 'O crime de fraude à licitação é formal, e sua consumação prescinde da comprovação do prejuízo ou da obtenção de vantagem.', null, 'TERCEIRA SEÇÃO', date '2021-02-10', 'DJe', date '2021-02-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 5, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (646, 'É irrelevante a natureza da verba trabalhista para fins de incidência da contribuição ao FGTS, visto que apenas as verbas elencadas em lei (art. 28, § 9º, da Lei n. 8.212/1991), em rol taxativo, estão excluídas da sua base de cálculo, por força do disposto no art. 15, § 6º, da Lei n. 8.036/1990.', null, 'PRIMEIRA SEÇÃO', date '2021-03-10', 'DJe', date '2021-03-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 5, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (647, 'São imprescritíveis as ações indenizatórias por danos morais e materiais decorrentes de atos de perseguição política com violação de direitos fundamentais ocorridos durante o regime militar.', null, 'PRIMEIRA SEÇÃO', date '2021-03-10', 'DJe', date '2021-03-15', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 5, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (648, 'A superveniência da sentença condenatória prejudica o pedido de trancamento da ação penal por falta de justa causa feito em habeas corpus.', null, 'TERCEIRA SEÇÃO', date '2021-04-14', 'DJe', date '2021-04-19', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 5, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (649, 'Não incide ICMS sobre o serviço de transporte interestadual de mercadorias destinadas ao exterior.', null, 'PRIMEIRA SEÇÃO', date '2021-04-28', 'DJe', date '2021-05-03', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 4, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (650, 'A autoridade administrativa não dispõe de discricionariedade para aplicar ao servidor pena diversa de demissão quando caraterizadas as hipóteses previstas no art. 132 da Lei n. 8.112/1990.', null, 'PRIMEIRA SEÇÃO', date '2021-09-22', 'DJe', date '2021-09-27', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 4, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (651, 'Compete à autoridade administrativa aplicar a servidor público a pena de demissão em razão da prática de improbidade administrativa, independentemente de prévia condenação, por autoridade judiciária, à perda da função pública.', null, 'PRIMEIRA SEÇÃO', date '2021-10-21', 'DJe', date '2021-10-25', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 4, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (652, 'A responsabilidade civil da Administração Pública por danos ao meio ambiente, decorrente de sua omissão no dever de fiscalização, é de caráter solidário, mas de execução subsidiária.', null, 'PRIMEIRA SEÇÃO', date '2021-12-02', 'DJe', date '2021-12-06', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 4, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (653, 'O pedido de parcelamento fiscal, ainda que indeferido, interrompe o prazo prescricional, pois caracteriza confissão extrajudicial do débito.', null, 'PRIMEIRA SEÇÃO', date '2021-12-02', 'DJe', date '2021-12-06', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 4, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (654, 'A tabela de preços máximos ao consumidor (PMC) publicada pela ABCFarma, adotada pelo Fisco para a fixação da base de cálculo do ICMS na sistemática da substituição tributária, não se aplica aos medicamentos destinados exclusivamente para uso de hospitais e clínicas.', null, 'PRIMEIRA SEÇÃO', date '2022-08-24', 'DJe', date '2022-08-29', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 4, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (655, 'Aplica-se à união estável contraída por septuagenário o regime da separação obrigatória de bens, comunicando-se os adquiridos na constância, quando comprovado o esforço comum.', null, 'SEGUNDA SEÇÃO', date '2022-11-09', 'DJe', date '2022-11-16', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 4, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (656, 'É válida a cláusula de prorrogação automática de fiança na renovação do contrato principal. A exoneração do fiador depende da notificação prevista no art. 835 do Código Civil.', null, 'SEGUNDA SEÇÃO', date '2022-11-09', 'DJe', date '2022-11-16', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 3, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (657, 'Atendidos os requisitos de segurada especial no RGPS e do período de carência, a indígena menor de 16 anos faz jus ao salário-maternidade.', null, 'PRIMEIRA SEÇÃO', date '2023-08-23', 'DJe', date '2023-08-28', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 3, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (658, 'O crime de apropriação indébita tributária pode ocorrer tanto em operações próprias, como em razão de substituição tributária.', null, 'TERCEIRA SEÇÃO', date '2023-09-13', 'DJe', date '2023-09-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 3, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (659, 'A fração de aumento em razão da prática de crime continuado deve ser fixada de acordo com o número de delitos cometidos, aplicando-se 1/6 pela prática de duas infrações, 1/5 para três, 1/4 para quatro, 1/3 para cinco, 1/2 para seis e 2/3 para sete ou mais infrações.', null, 'TERCEIRA SEÇÃO', date '2023-09-13', 'DJe', date '2023-09-08', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 3, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (660, 'A posse, pelo apenado, de aparelho celular ou de seus componentes essenciais constitui falta grave.', null, 'TERCEIRA SEÇÃO', date '2023-09-13', 'DJe', date '2023-09-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 3, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (661, 'A falta grave prescinde da perícia do celular apreendido ou de seus componentes essenciais.', null, 'TERCEIRA SEÇÃO', date '2023-09-13', 'DJe', date '2023-09-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 3, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (662, 'Para a prorrogação do prazo de permanência no sistema penitenciário federal, é prescindível a ocorrência de fato novo; basta constar, em decisão fundamentada, a persistência dos motivos que ensejaram a transferência inicial do preso.', null, 'TERCEIRA SEÇÃO', date '2023-09-13', 'DJe', date '2023-09-18', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 3, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (663, 'A pensão por morte de servidor público federal pode ser concedida ao filho inválido de qualquer idade, desde que a invalidez seja anterior ao óbito.', null, 'PRIMEIRA SEÇÃO', date '2023-11-08', 'DJe', date '2023-11-13', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 3, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (664, 'É inaplicável a consunção entre o delito de embriaguez ao volante e o de condução de veículo automotor sem habilitação.', null, 'TERCEIRA SEÇÃO', date '2023-11-08', 'DJe', date '2023-11-13', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 2, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (665, 'O controle jurisdicional do processo administrativo disciplinar restringe-se ao exame da regularidade do procedimento e da legalidade do ato, à luz dos princípios do contraditório, da ampla defesa e do devido processo legal, não sendo possível incursão no mérito administrativo, ressalvadas as hipóteses de flagrante ilegalidade, teratologia ou manifesta desproporcionalidade da sanção aplicada.', null, 'PRIMEIRA SEÇÃO', date '2023-12-13', 'DJe', date '2023-12-14', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 2, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (666, 'A legitimidade passiva, em demandas que visam à restituição de contribuições de terceiros, está vinculada à capacidade tributária ativa; assim, nas hipóteses em que as entidades terceiras são meras destinatárias das contribuições, não possuem elas legitimidade ad causam para figurar no polo passivo, juntamente com a União.', null, 'PRIMEIRA SEÇÃO', date '2024-04-18', 'DJe', date '2024-04-22', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 2, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (667, 'Eventual aceitação de proposta de suspensão condicional do processo não prejudica a análise do pedido de trancamento de ação penal.', null, 'TERCEIRA SEÇÃO', date '2024-04-18', 'DJe', date '2024-04-22', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 2, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (668, 'Não é hediondo o delito de porte ou posse de arma de fogo de uso permitido, ainda que com numeração, marca ou qualquer outro sinal de identificação raspado, suprimido ou adulterado.', null, 'TERCEIRA SEÇÃO', date '2024-04-18', 'DJe', date '2024-04-22', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 2, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (669, 'O fornecimento de bebida alcoólica a criança ou adolescente, após o advento da Lei n. 13.106, de 17 de março de 2015, configura o crime previsto no art. 243 do ECA.', null, 'TERCEIRA SEÇÃO', date '2024-06-12', 'DJe', date '2024-06-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 2, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (670, 'Nos crimes sexuais cometidos contra a vítima em situação de vulnerabilidade temporária, em que ela recupera suas capacidades físicas e mentais e o pleno discernimento para decidir acerca da persecução penal de seu ofensor, a ação penal é pública condicionada à representação se o fato houver sido praticado na vigência da redação conferida ao art. 225 do Código Penal pela Lei n. 12.015, de 2009.', null, 'TERCEIRA SEÇÃO', date '2024-06-20', 'DJe', date '2024-06-24', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 2, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (671, 'Não incide o IPI quando sobrevém furto ou roubo do produto industrializado após sua saída do estabelecimento industrial ou equiparado e antes de sua entrega ao adquirente.', null, 'PRIMEIRA SEÇÃO', date '2024-06-20', 'DJe', date '2024-06-24', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 1, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (672, 'A alteração da capitulação legal da conduta do servidor, por si só, não enseja a nulidade do processo administrativo disciplinar.', null, 'PRIMEIRA SEÇÃO', date '2024-09-11', 'DJe', date '2024-09-16', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 1, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (673, 'A comprovação da regular notificação do executado para o pagamento da dívida de anuidade de conselhos de classe ou, em caso de recurso, o esgotamento das instâncias administrativas são requisitos indispensáveis à constituição e execução do crédito.', null, 'PRIMEIRA SEÇÃO', date '2024-09-11', 'DJe', date '2024-09-16', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 1, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (674, 'A autoridade administrativa pode se utilizar de fundamentação per relationem nos processos disciplinares.', null, 'PRIMEIRA SEÇÃO', date '2024-11-13', 'DJe', date '2024-11-25', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 1, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (675, 'É legítima a atuação dos órgãos de defesa do consumidor na aplicação de sanções administrativas previstas no CDC quando a conduta praticada ofender direito consumerista, o que não exclui nem inviabiliza a atuação do órgão ou entidade de controle quando a atividade é regulada.', null, 'PRIMEIRA SEÇÃO', date '2024-11-13', 'DJe', date '2024-11-25', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 1, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta'),
  (676, 'Em razão da Lei n. 13.964/2019, não é mais possível ao juiz, de ofício, decretar ou converter prisão em flagrante em prisão preventiva.', null, 'TERCEIRA SEÇÃO', date '2024-12-11', 'DJe', date '2024-12-17', 'vigente', null, null, 'STJ — Verbetes das Súmulas (lista oficial)', 'VerbetesSTJ.pdf', 1, 'https://scon.stj.jus.br/SCON/sumstj/', 'lista de súmulas do STJ', date '2026-08-04', 'alta')
on conflict (numero) do update set
  enunciado = excluded.enunciado, ramo = excluded.ramo,
  orgao = excluded.orgao, data_julgamento = excluded.data_julgamento,
  veiculo = excluded.veiculo, data_publicacao = excluded.data_publicacao,
  situacao = excluded.situacao, nota_situacao = excluded.nota_situacao,
  redacao_anterior = excluded.redacao_anterior,
  fonte_documento = excluded.fonte_documento, fonte_arquivo = excluded.fonte_arquivo,
  fonte_pagina = excluded.fonte_pagina, fonte_url = excluded.fonte_url,
  situacao_fonte = excluded.situacao_fonte, situacao_data = excluded.situacao_data,
  confianca = excluded.confianca;

-- A RPC passa a ler a tabela própria, com situação e redação anterior. O tipo de
-- retorno muda, por isso o drop antes do create.
drop function if exists public.stj_sumula(int, text);

create function public.stj_sumula(p_numero int, p_tese text default null)
returns table (
  numero_tese      int,
  area             text,
  enunciado        text,
  fonte_arquivo    text,
  fonte_pagina     int,
  fonte_url        text,
  sim              real,
  situacao         text,
  nota_situacao    text,
  situacao_data    date,
  data_publicacao  date,
  redacao_anterior text,
  sim_anterior     real
) language sql stable security definer set search_path = public as $$
  select s.numero,
         s.ramo,
         s.enunciado,
         s.fonte_arquivo,
         s.fonte_pagina,
         s.fonte_url,
         case when coalesce(p_tese, '') = '' then null
              else greatest(word_similarity(p_tese, s.enunciado),
                            similarity(p_tese, s.enunciado)) end as sim,
         s.situacao,
         s.nota_situacao,
         s.situacao_data,
         s.data_publicacao,
         s.redacao_anterior,
         -- Semelhança contra o texto ANTIGO: é o que permite dizer "você citou a
         -- redação anterior" em vez de apenas apontar divergência.
         case when coalesce(p_tese, '') = '' or s.redacao_anterior is null then null
              else greatest(word_similarity(p_tese, s.redacao_anterior),
                            similarity(p_tese, s.redacao_anterior)) end as sim_anterior
    from public.stj_sumulas s
   where s.numero = p_numero
   limit 1
$$;

revoke all on function public.stj_sumula(int, text) from public;
grant execute on function public.stj_sumula(int, text) to authenticated;
grant execute on function public.stj_sumula(int, text) to service_role;

comment on function public.stj_sumula(int, text) is
  'Enunciado, situação e redação anterior de súmula do STJ, da lista oficial. Usada pelo Nível 1 do Verificador.';
